<body>

    <header class="no-print" style="margin-bottom: 2rem; display: flex; justify-content: space-between; align-items: center;">
        <div>
            <h1 style="margin:0;">Fridge Clearing Dinner Board</h1>
            <p style="margin:0; color:#64748b;">All updates auto-save locally to your browser.</p>
        </div>
        <button class="clear-btn" onclick="clearBoard()">🧹 Clear Whole Board</button>
    </header>

    <div class="grid">
        <div class="card no-print">
            <h2>1. What's in the Fridge?</h2>
            <div class="input-group">
                <input type="text" id="ingName" placeholder="e.g., Grilled chicken, Spinach, Rice">
                <select id="ingRisk" style="padding: 0.5rem; border: 1px solid var(--border-color); border-radius: 4px;">
                    <option value="1">Staple / Safe</option>
                    <option value="5">High Risk / Perishable</option>
                </select>
                <button onclick="addIngredient()">Add</button>
            </div>
            <ul id="ingredientList" class="ingredient-list"></ul>

            <button class="suggest-btn" onclick="triggerAutoSuggestions()">✨ Auto-Suggest Dinner Choices</button>
        </div>

        <div class="card no-print">
            <h2>2. Custom Dinner Concept</h2>
            <div class="input-group" style="flex-direction: column; gap: 0.75rem;">
                <input type="text" id="recipeName" placeholder="Meal Name (e.g., Kitchen Sink Frittata)">
                <textarea id="recipeNotes" placeholder="Quick prep steps / notes..."></textarea>

                <div style="margin: 0.5rem 0;">
                    <span style="font-size: 0.875rem; font-weight: 600; display: block; margin-bottom: 0.25rem;">Select used ingredients:</span>
                    <div id="recipeIngredientsCheckboxes" style="max-height: 100px; overflow-y: auto; border: 1px solid var(--border-color); padding: 0.5rem; border-radius: 4px;">
                        </div>
                </div>

                <button onclick="addRecipe()">Add Custom Idea</button>
            </div>
        </div>
    </div>

    <div class="card" id="outputSection">
        <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #e2e8f0; padding-bottom: 0.75rem; margin-bottom: 1rem;">
            <h2 style="margin:0;">Tonight's Ranked Menu Options</h2>
            <div class="action-bar no-print" style="margin:0;">
                <button class="export-btn" onclick="window.print()">🖨️ Print Menu Plan</button>
                <button class="export-btn" onclick="exportAsText()">📋 Export Text</button>
            </div>
        </div>

        <div id="rankedContainer">
            </div>
    </div>

    <script>
        // Core data models
        let ingredients = [];
        let recipes = [];

        // Prebuilt Archetype Recipes
        const dynamicPatterns = [
            { name: "Kitchen Sink Scramble / Frittata", notes: "Whisk up eggs, chop inventory components, and cook over medium heat until set.", requiresOneOf: ["Eggs", "Cheese", "Cream"], flexibleFillers: true },
            { name: "Clear-Out Stir Fry & Rice", notes: "High heat skillet flash-fry. Toss with soy sauce or available condiments over a hot grain base.", requiresOneOf: ["Rice", "Grains", "Noodles"], flexibleFillers: true },
            { name: "The Everything Loaded Bowl", notes: "Warm up base elements. Reheat any proteins or cooked leftovers, then layer everything in a single bowl with a quick sauce choice.", requiresOneOf: ["Rice", "Quinoa", "Spinach", "Greens", "Lettuce"], flexibleFillers: true },
            { name: "Pan-Fried Quesadilla / Melt", notes: "Crisp up your starch vehicle in a hot buttered pan. Pack with cheese and shifting protein ingredients until melted.", requiresOneOf: ["Tortillas", "Bread", "Cheese"], flexibleFillers: true },
            { name: "Rustic Fridge Clearing Soup", notes: "Simmer broth or cream bases. Toss in any chopped cooked meats and wilting green roughage until everything is uniform and hot.", requiresOneOf: ["Broth", "Heavy Cream", "Water", "Soup"], flexibleFillers: true }
        ];

        // LocalStorage Helpers
        function saveToLocalStorage() {
            localStorage.setItem('fridge_board_ingredients', JSON.stringify(ingredients));
            localStorage.setItem('fridge_board_recipes', JSON.stringify(recipes));
        }

        function loadFromLocalStorage() {
            const storedIngredients = localStorage.getItem('fridge_board_ingredients');
            const storedRecipes = localStorage.getItem('fridge_board_recipes');

            if (storedIngredients) {
                ingredients = JSON.parse(storedIngredients);
            } else {
                // Initial baseline seed data on completely clear start
                ingredients = [
                    { id: 1, name: "Cooked Chicken", risk: 5 },
                    { id: 2, name: "Spinach", risk: 5 },
                    { id: 3, name: "Heavy Cream", risk: 5 },
                    { id: 4, name: "Rice", risk: 1 },
                    { id: 5, name: "Eggs", risk: 1 }
                ];
            }

            if (storedRecipes) {
                recipes = JSON.parse(storedRecipes);
            } else {
                recipes = [];
            }
        }

        function clearBoard() {
            if(confirm("Are you sure you want to clear your current inventory and all meal configurations?")) {
                ingredients = [];
                recipes = [];
                saveToLocalStorage();
                renderIngredients();
                renderRecipes();
            }
        }

        // App Initialization
        function init() {
            loadFromLocalStorage();
            renderIngredients();
            if (recipes.length === 0 && ingredients.length > 0) {
                autoSuggestMeals(false); // Silent build patterns if zero user entries exist
            } else {
                renderRecipes();
            }
        }

        // Inventory Management
        function addIngredient() {
            const nameInput = document.getElementById('ingName');
            const riskInput = document.getElementById('ingRisk');

            if (!nameInput.value.trim()) return;

            ingredients.push({
                id: Date.now(),
                name: nameInput.value.trim(),
                risk: parseInt(riskInput.value)
            });

            nameInput.value = '';
            riskInput.value = '1';

            saveToLocalStorage();
            renderIngredients();
            autoSuggestMeals(false); // Dynamically hook fresh rules without wiping user recipes
        }

        function deleteIngredient(id) {
            ingredients = ingredients.filter(ing => ing.id !== id);
            recipes.forEach(r => {
                r.ingredientIds = r.ingredientIds.filter(ingId => ingId !== id);
            });
            saveToLocalStorage();
            renderIngredients();
            renderRecipes();
        }

        function renderIngredients() {
            const list = document.getElementById('ingredientList');
            const checkboxContainer = document.getElementById('recipeIngredientsCheckboxes');

            list.innerHTML = '';
            checkboxContainer.innerHTML = '';

            if(ingredients.length === 0) {
                list.innerHTML = '<li style="color: #64748b; font-style: italic;">No items listed.</li>';
                checkboxContainer.innerHTML = '<span style="color: #64748b; font-size: 0.875rem;">Add ingredients first.</span>';
                return;
            }

            ingredients.forEach(ing => {
                const li = document.createElement('li');
                li.className = 'ingredient-item';
                li.innerHTML = `
                    <div class="ingredient-details">
                        <span class="badge ${ing.risk === 5 ? 'badge-high' : 'badge-normal'}">
                            ${ing.risk === 5 ? 'RISKY' : 'SAFE'}
                        </span>
                        <span>${ing.name}</span>
                    </div>
                    <button class="danger-btn" onclick="deleteIngredient(${ing.id})">Remove</button>
                `;
                list.appendChild(li);

                const label = document.createElement('label');
                label.style.display = 'flex';
                label.style.alignItems = 'center';
                label.style.gap = '0.5rem';
                label.style.marginBottom = '0.25rem';
                label.style.cursor = 'pointer';
                label.innerHTML = `
                    <input type="checkbox" value="${ing.id}" class="recipe-ing-check">
                    <span>${ing.name} ${ing.risk === 5 ? '⚠️' : ''}</span>
                `;
                checkboxContainer.appendChild(label);
            });
        }

        // Generation Mechanism Logic
        function triggerAutoSuggestions() {
            autoSuggestMeals(true);
        }

        function autoSuggestMeals(alertUser) {
            // Filter custom ideas so we don't drop user-added designs
            recipes = recipes.filter(r => r.isCustom);

            if (ingredients.length === 0) {
                renderRecipes();
                return;
            }

            dynamicPatterns.forEach((pattern, patternIdx) => {
                let matchedIngredientIds = [];
                let hasAnchorIngredient = false;

                ingredients.forEach(ing => {
                    const matchesAnchor = pattern.requiresOneOf.some(keyword => 
                        ing.name.toLowerCase().includes(keyword.toLowerCase())
                    );

                    if (matchesAnchor) {
                        hasAnchorIngredient = true;
                        matchedIngredientIds.push(ing.id);
                    } else if (pattern.flexibleFillers) {
                        matchedIngredientIds.push(ing.id);
                    }
                });

                if (hasAnchorIngredient && matchedIngredientIds.length > 0) {
                    recipes.push({
                        id: `auto-${patternIdx}-${Date.now()}`,
                        name: pattern.name,
                        notes: pattern.notes,
                        ingredientIds: matchedIngredientIds,
                        isCustom: false
                    });
                }
            });

            saveToLocalStorage();
            renderRecipes();
            if(alertUser) alert("Re-scanned items and synchronized baseline choices!");
        }

        // Custom Manual Entry 
        function addRecipe() {
            const nameInput = document.getElementById('recipeName');
            const notesInput = document.getElementById('recipeNotes');
            const checkboxes = document.querySelectorAll('.recipe-ing-check:checked');

            if (!nameInput.value.trim()) return;

            const selectedIds = Array.from(checkboxes).map(cb => parseInt(cb.value));

            recipes.push({
                id: Date.now(),
                name: nameInput.value.trim(),
                notes: notesInput.value.trim(),
                ingredientIds: selectedIds,
                isCustom: true
            });

            nameInput.value = '';
            notesInput.value = '';

            saveToLocalStorage();
            renderRecipes();
        }

        function deleteRecipe(id) {
            recipes = recipes.filter(r => String(r.id) !== String(id));
            saveToLocalStorage();
            renderRecipes();
        }

        // Matrix Rendering Engine
        function renderRecipes() {
            const container = document.getElementById('rankedContainer');
            container.innerHTML = '';

            if (recipes.length === 0) {
                container.innerHTML = '<p style="color: #64748b; font-style: italic;">No meal paths active. Check patterns or type custom layouts above.</p>';
                return;
            }

            const ranked = recipes.map(recipe => {
                let score = 0;
                let usedNames = [];
                let highRiskCount = 0;

                recipe.ingredientIds.forEach(id => {
                    const ing = ingredients.find(i => i.id === id);
                    if (ing) {
                        score += ing.risk;
                        usedNames.push(ing.name);
                        if (ing.risk === 5) highRiskCount++;
                    }
                });

                return { ...recipe, score, highRiskCount, usedNames };
            });

            // Priority calculations based on rescuing highly perishable stock components
            ranked.sort((a, b) => (b.highRiskCount - a.highRiskCount) || (b.score - a.score));

            ranked.forEach((recipe, idx) => {
                const item = document.createElement('div');
                item.className = 'idea-item';

                const topOptionBadge = idx === 0 && recipe.highRiskCount > 0 
                    ? `<span class="score-tag" style="background-color: var(--danger-bg); color: var(--danger-color)">🔥 CRITICAL PATH CHOICE</span>` 
                    : `<span class="score-tag">Rank #${idx + 1}</span>`;

                const typeBadge = recipe.isCustom 
                    ? `<span class="no-print" style="font-size:0.75rem; color:var(--primary-color); border:1px solid var(--primary-color); padding:1px 4px; border-radius:3px; margin-left:0.5rem;">Custom</span>`
                    : `<span class="no-print" style="font-size:0.75rem; color:var(--suggest-color); border:1px solid var(--suggest-color); padding:1px 4px; border-radius:3px; margin-left:0.5rem;">Suggested</span>`;

                item.innerHTML = `
                    <div class="idea-header">
                        <h3 style="margin: 0; display:flex; align-items:center;">${recipe.name} ${typeBadge}</h3>
                        ${topOptionBadge}
                    </div>
                    <p style="margin: 0.5rem 0; font-size: 0.95rem; white-space: pre-wrap;">${recipe.notes || 'No prep execution details listed.'}</p>
                    <div class="used-ingredients">
                        <strong>Incorporates:</strong> ${recipe.usedNames.length > 0 ? recipe.usedNames.join(', ') : 'No tracked variables used'} 
                        <span style="margin-left: 0.5rem; color: #475569;">(Rescues ${recipe.highRiskCount} high-threat ingredients)</span>
                    </div>
                    <button class="danger-btn no-print" style="margin-top: 0.75rem;" onclick="deleteRecipe('${recipe.id}')">Dismiss Meal</button>
                `;
                container.appendChild(item);
            });
        }

        // Plain Text Clipboard String Generation
        function exportAsText() {
            let outputText = "MY FRIDGE OUTLINE & DINNER PLAN\n=================================\n\n";

            const ranked = recipes.map(recipe => {
                let score = 0;
                let highRiskCount = 0;
                let usedNames = [];
                recipe.ingredientIds.forEach(id => {
                    const ing = ingredients.find(i => i.id === id);
                    if (ing) {
                        score += ing.risk;
                        if (ing.risk === 5) highRiskCount++;
                        usedNames.push(ing.name);
                    }
                });
                return { ...recipe, score, highRiskCount, usedNames };
            }).sort((a, b) => (b.highRiskCount - a.highRiskCount) || (b.score - a.score));

            outputText += "RANKED CHOICES:\n";
            ranked.forEach((r, i) => {
                outputText += `${i + 1}. ${r.name} [Type: ${r.isCustom ? 'Custom' : 'Suggested'}] ${i === 0 && r.highRiskCount > 0 ? ' <- TOP PRIORITY' : ''}\n`;
                outputText += `   Steps: ${r.notes || 'N/A'}\n`;
                outputText += `   Clears: ${r.usedNames.join(', ')}\n\n`;
            });

            const tempTexarea = document.createElement('textarea');
            tempTexarea.value = outputText;
            document.body.appendChild(tempTexarea);
            tempTexarea.select();
            document.execCommand('copy');
            document.body.removeChild(tempTexarea);

            alert('Dinner plan exported to your clipboard!');
        }

        window.onload = init;
    </script>
</body>
</html>

